def accmin(aa):
    h = len(aa)
    w = len(aa[0])
    res = [[inf]*w for _ in range(h)]
    res[0][0] = aa[0][0]
    for i in range(1, h):
        res[i][0] = min(res[i-1][0], aa[i][0])
    for j in range(1, w):
        res[0][j] = min(res[0][j-1], aa[0][j])
    for i in range(1, h):
        for j in range(1, w):
            res[i][j] = min(res[i-1][j], res[i][j-1], aa[i][j])
    return res

def accmax(aa):
    h = len(aa)
    w = len(aa[0])
    res = [[-1]*w for _ in range(h)]
    res[0][0] = aa[0][0]
    for i in range(1, h):
        res[i][0] = max(res[i-1][0], aa[i][0])
    for j in range(1, w):
        res[0][j] = max(res[0][j-1], aa[0][j])
    for i in range(1, h):
        for j in range(1, w):
            res[i][j] = max(res[i-1][j], res[i][j-1], aa[i][j])
    return res

