        ii.append(aa[i].pop())
    # p2D(aa)
    # print()
    # print(ii)

    lu = accmax(aa)

    aa.reverse()
    ld = accmin(aa)
    ld.reverse()

    for i in range(h): aa[i].reverse()
    rd = accmax(aa)
