    ans = ["R"]*h
    for i in range(h-1):
        for j in range(w-1):
            if lu[i][j] < ld[i+1][j] and ru[i][j+1] > rd[i+1][j+1]:
                for k in ii[:i+1]: ans[k] = "B"
                print("YES")
                print("".join(ans), j+1)
                return

